class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None
        self.random = None

def cloneTree(root):
    if not root:
        return None

    # Dictionary to hold the mapping from original nodes to their clones
    node_map = {}

    # First pass: create all nodes and store them in a dictionary
    def create_nodes(node):
        if not node:
            return None
        new_node = Node(node.data)
        node_map[node] = new_node
        new_node.left = create_nodes(node.left)
        new_node.right = create_nodes(node.right)
        return new_node

    # Second pass: assign random pointers
    def assign_random_pointers(node):
        if not node:
            return
        if node.random:
            node_map[node].random = node_map[node.random]
        assign_random_pointers(node.left)
        assign_random_pointers(node.right)

    create_nodes(root)
    assign_random_pointers(root)

    return node_map[root]
